CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_accept_custom_quote` (IN `p_custom_order_id` INT UNSIGNED, IN `p_payment_method_id` INT UNSIGNED, IN `p_gcash_ref` VARCHAR(20), IN `p_fulfillment` VARCHAR(10), IN `p_address_id` INT UNSIGNED, IN `p_first` VARCHAR(50), IN `p_last` VARCHAR(50), IN `p_pickup_time` TIME, OUT `p_order_id` INT UNSIGNED)   BEGIN
  DECLARE v_customer INT UNSIGNED;
  DECLARE v_status VARCHAR(10);
  DECLARE v_price DECIMAL(8,2);
  DECLARE v_date DATE;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT customer_id, quote_status, quoted_price, preferred_date
    INTO v_customer, v_status, v_price, v_date
  FROM CUSTOM_ORDERS WHERE id = p_custom_order_id FOR UPDATE;
  IF v_status IS NULL OR v_status <> 'Quoted' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a quoted custom order can be accepted';
  END IF;
  SET @current_user_id = v_customer;
  INSERT INTO ORDERS (customer_id, payment_method_id, total_amount, gcash_ref_number, preferred_date)
  VALUES (v_customer, p_payment_method_id, v_price, p_gcash_ref, v_date);
  SET p_order_id = LAST_INSERT_ID();
  UPDATE CUSTOM_ORDERS SET order_id = p_order_id, quote_status = 'Accepted' WHERE id = p_custom_order_id;
  CALL sp_set_fulfillment(p_order_id, p_fulfillment, p_address_id, p_first, p_last, p_pickup_time);
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_confirm_order` (IN `p_order_id` INT UNSIGNED, IN `p_staff_id` INT UNSIGNED)   BEGIN
  DECLARE v_status VARCHAR(10);
  DECLARE v_product, v_qty INT UNSIGNED;
  DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE cur CURSOR FOR SELECT product_id, quantity FROM ORDER_ITEMS WHERE order_id = p_order_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  SELECT order_status INTO v_status FROM ORDERS WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL OR v_status <> 'Pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a Pending order can be confirmed';
  END IF;
  OPEN cur;
  item_loop: LOOP
    FETCH cur INTO v_product, v_qty;
    IF v_done THEN LEAVE item_loop; END IF;
    CALL sp_deduct_product_stock(v_product, v_qty);
  END LOOP;
  CLOSE cur;
  UPDATE ORDERS SET order_status = 'Confirmed' WHERE id = p_order_id;
  INSERT INTO SALES (order_id, sale_date, recorded_by_staff_id) VALUES (p_order_id, CURDATE(), p_staff_id);
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_deduct_product_stock` (IN `p_product_id` INT UNSIGNED, IN `p_qty` INT UNSIGNED)   BEGIN
  DECLARE v_need INT UNSIGNED DEFAULT p_qty;
  DECLARE v_id, v_rem, v_take INT UNSIGNED;
  DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE cur CURSOR FOR
    SELECT id, stock_remaining FROM INVENTORY_BATCHES
    WHERE product_id = p_product_id AND stock_remaining > 0
    ORDER BY baked_date, id FOR UPDATE;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_id, v_rem;
    IF v_done OR v_need = 0 THEN LEAVE read_loop; END IF;
    SET v_take = LEAST(v_rem, v_need);
    UPDATE INVENTORY_BATCHES SET stock_remaining = stock_remaining - v_take WHERE id = v_id;
    SET v_need = v_need - v_take;
  END LOOP;
  CLOSE cur;
  IF v_need > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Insufficient product stock';
  END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_order_details` (IN `p_order_id` INT UNSIGNED, IN `p_user_id` INT UNSIGNED)   BEGIN
  CALL sp_log_retrieve(p_user_id, 'ORDERS', p_order_id);
  SELECT * FROM v_order_summary WHERE order_id = p_order_id;
  SELECT p.product_name, oi.quantity, oi.unit_price, oi.quantity * oi.unit_price AS line_total
  FROM ORDER_ITEMS oi JOIN PRODUCTS p ON p.id = oi.product_id
  WHERE oi.order_id = p_order_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_log_retrieve` (IN `p_user_id` INT UNSIGNED, IN `p_table` VARCHAR(64), IN `p_record` INT UNSIGNED)   BEGIN
  CALL sp_write_audit(p_user_id, p_table, p_record, 'RETRIEVE');
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_mark_priority_ordered` (IN `p_raw_material_id` INT UNSIGNED)   BEGIN
  DECLARE v_rl INT UNSIGNED;
  SELECT id INTO v_rl FROM REORDER_LEVEL WHERE raw_material_id = p_raw_material_id;
  IF v_rl IS NOT NULL THEN
    UPDATE PRIORITY_1 SET priority_status = 'Ordered' WHERE reorder_level_id = v_rl AND priority_status = 'Open';
    UPDATE PRIORITY_2 SET priority_status = 'Ordered' WHERE reorder_level_id = v_rl AND priority_status = 'Open';
    UPDATE PRIORITY_3 SET priority_status = 'Ordered' WHERE reorder_level_id = v_rl AND priority_status = 'Open';
  END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_place_order` (IN `p_customer_id` INT UNSIGNED, IN `p_payment_method_id` INT UNSIGNED, IN `p_preferred_date` DATE, IN `p_gcash_ref` VARCHAR(20), IN `p_fulfillment` VARCHAR(10), IN `p_address_id` INT UNSIGNED, IN `p_first` VARCHAR(50), IN `p_last` VARCHAR(50), IN `p_pickup_time` TIME, OUT `p_order_id` INT UNSIGNED)   BEGIN
  DECLARE v_cart INT UNSIGNED;
  DECLARE v_method VARCHAR(30);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_customer_id;
  SELECT id INTO v_cart FROM SHOPPING_CART WHERE customer_id = p_customer_id FOR UPDATE;
  IF v_cart IS NULL OR NOT EXISTS (SELECT 1 FROM CART_ITEMS WHERE cart_id = v_cart) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cart is empty';
  END IF;
  IF EXISTS (SELECT 1 FROM CART_ITEMS ci JOIN PRODUCTS p ON p.id = ci.product_id
             WHERE ci.cart_id = v_cart AND p.is_archived = 1) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cart contains an archived product';
  END IF;
  SELECT method_name INTO v_method FROM PAYMENT_METHOD WHERE id = p_payment_method_id AND is_active = 1;
  IF v_method IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payment method is not available';
  END IF;
  IF v_method = 'GCash' AND p_gcash_ref IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'GCash reference number is required';
  END IF;
  INSERT INTO ORDERS (customer_id, payment_method_id, total_amount, gcash_ref_number, preferred_date)
  VALUES (p_customer_id, p_payment_method_id, 0, p_gcash_ref, p_preferred_date);
  SET p_order_id = LAST_INSERT_ID();
  INSERT INTO ORDER_ITEMS (order_id, product_id, unit_price, quantity)
  SELECT p_order_id, ci.product_id, p.product_price, ci.quantity
  FROM CART_ITEMS ci JOIN PRODUCTS p ON p.id = ci.product_id WHERE ci.cart_id = v_cart;
  CALL sp_set_fulfillment(p_order_id, p_fulfillment, p_address_id, p_first, p_last, p_pickup_time);
  DELETE FROM CART_ITEMS WHERE cart_id = v_cart;
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_recalc_order_total` (IN `p_order_id` INT UNSIGNED)   BEGIN
  UPDATE ORDERS
  SET total_amount = COALESCE((SELECT SUM(unit_price * quantity) FROM ORDER_ITEMS WHERE order_id = p_order_id), 0)
  WHERE id = p_order_id
    AND NOT EXISTS (SELECT 1 FROM CUSTOM_ORDERS WHERE order_id = p_order_id);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_receive_purchase_order` (IN `p_po_id` INT UNSIGNED, IN `p_staff_id` INT UNSIGNED)   BEGIN
  DECLARE v_status VARCHAR(10);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  SELECT purchase_order_status INTO v_status FROM PURCHASE_ORDER WHERE id = p_po_id FOR UPDATE;
  IF v_status IS NULL OR v_status <> 'Ordered' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only an Ordered purchase order can be received';
  END IF;
  INSERT INTO STOCK_IN (raw_material_id, purchase_order_id, quantity_in, unit_cost, received_date, received_by_staff_id)
  SELECT raw_material_id, p_po_id, quantity_ordered, unit_cost, CURDATE(), p_staff_id
  FROM PURCHASE_ORDER_ITEMS WHERE purchase_order_id = p_po_id;
  UPDATE PURCHASE_ORDER SET purchase_order_status = 'Received' WHERE id = p_po_id;
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_record_discard` (IN `p_batch_id` INT UNSIGNED, IN `p_qty` INT UNSIGNED, IN `p_reason` VARCHAR(20), IN `p_staff_id` INT UNSIGNED, OUT `p_discard_id` INT UNSIGNED)   BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  INSERT INTO DISCARDED_ITEMS (batch_id, quantity_discarded, discard_reason, discard_date, discarded_by_staff_id)
  VALUES (p_batch_id, p_qty, p_reason, CURDATE(), p_staff_id);
  SET p_discard_id = LAST_INSERT_ID();
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_refresh_priority` (IN `p_raw_material_id` INT UNSIGNED)   main: BEGIN
  DECLARE v_rl INT UNSIGNED;
  DECLARE v_qty, v_p1, v_p2, v_p3 DECIMAL(10,3);
  DECLARE v_arch BOOLEAN;
  DECLARE v_status VARCHAR(10);
  DECLARE v_level TINYINT DEFAULT 0;
  SELECT rl.id, rm.quantity_on_hand, rl.priority1_qty, rl.priority2_qty, rl.priority3_qty, rm.is_archived
    INTO v_rl, v_qty, v_p1, v_p2, v_p3, v_arch
  FROM REORDER_LEVEL rl JOIN RAW_MATERIALS rm ON rm.id = rl.raw_material_id
  WHERE rl.raw_material_id = p_raw_material_id;
  IF v_rl IS NULL THEN LEAVE main; END IF;
  SET v_status = COALESCE((SELECT priority_status FROM PRIORITY_1 WHERE reorder_level_id = v_rl),
                          (SELECT priority_status FROM PRIORITY_2 WHERE reorder_level_id = v_rl),
                          (SELECT priority_status FROM PRIORITY_3 WHERE reorder_level_id = v_rl), 'Open');
  IF v_arch = 0 THEN
    IF v_qty <= v_p1 THEN SET v_level = 1;
    ELSEIF v_qty <= v_p2 THEN SET v_level = 2;
    ELSEIF v_qty <= v_p3 THEN SET v_level = 3;
    END IF;
  END IF;
  IF v_level <> 1 THEN DELETE FROM PRIORITY_1 WHERE reorder_level_id = v_rl; END IF;
  IF v_level <> 2 THEN DELETE FROM PRIORITY_2 WHERE reorder_level_id = v_rl; END IF;
  IF v_level <> 3 THEN DELETE FROM PRIORITY_3 WHERE reorder_level_id = v_rl; END IF;
  IF v_level = 1 THEN INSERT IGNORE INTO PRIORITY_1 (reorder_level_id, priority_status) VALUES (v_rl, v_status); END IF;
  IF v_level = 2 THEN INSERT IGNORE INTO PRIORITY_2 (reorder_level_id, priority_status) VALUES (v_rl, v_status); END IF;
  IF v_level = 3 THEN INSERT IGNORE INTO PRIORITY_3 (reorder_level_id, priority_status) VALUES (v_rl, v_status); END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_set_fulfillment` (IN `p_order_id` INT UNSIGNED, IN `p_fulfillment` VARCHAR(10), IN `p_address_id` INT UNSIGNED, IN `p_first` VARCHAR(50), IN `p_last` VARCHAR(50), IN `p_pickup_time` TIME)   BEGIN
  IF p_fulfillment = 'Delivery' THEN
    INSERT INTO DELIVERY (order_id, address_id, recipient_first_name, recipient_last_name)
    VALUES (p_order_id, p_address_id, p_first, p_last);
  ELSEIF p_fulfillment = 'Pick-up' THEN
    INSERT INTO PICKUP (order_id, pickup_time) VALUES (p_order_id, p_pickup_time);
  ELSE
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Fulfillment must be Delivery or Pick-up';
  END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sync_product_stock` (IN `p_product_id` INT UNSIGNED)   BEGIN
  UPDATE PRODUCTS
  SET total_stock = COALESCE((SELECT SUM(stock_remaining) FROM INVENTORY_BATCHES WHERE product_id = p_product_id), 0),
      baked_date  = (SELECT MAX(baked_date) FROM INVENTORY_BATCHES WHERE product_id = p_product_id)
  WHERE id = p_product_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_unmark_priority_ordered` (IN `p_po_id` INT UNSIGNED)   BEGIN
  UPDATE PRIORITY_1 pr JOIN REORDER_LEVEL rl ON rl.id = pr.reorder_level_id
    JOIN PURCHASE_ORDER_ITEMS poi ON poi.raw_material_id = rl.raw_material_id AND poi.purchase_order_id = p_po_id
  SET pr.priority_status = 'Open'
  WHERE pr.priority_status = 'Ordered' AND NOT EXISTS (
    SELECT 1 FROM PURCHASE_ORDER_ITEMS x JOIN PURCHASE_ORDER po ON po.id = x.purchase_order_id
    WHERE x.raw_material_id = rl.raw_material_id AND po.id <> p_po_id AND po.purchase_order_status IN ('Pending','Ordered'));
  UPDATE PRIORITY_2 pr JOIN REORDER_LEVEL rl ON rl.id = pr.reorder_level_id
    JOIN PURCHASE_ORDER_ITEMS poi ON poi.raw_material_id = rl.raw_material_id AND poi.purchase_order_id = p_po_id
  SET pr.priority_status = 'Open'
  WHERE pr.priority_status = 'Ordered' AND NOT EXISTS (
    SELECT 1 FROM PURCHASE_ORDER_ITEMS x JOIN PURCHASE_ORDER po ON po.id = x.purchase_order_id
    WHERE x.raw_material_id = rl.raw_material_id AND po.id <> p_po_id AND po.purchase_order_status IN ('Pending','Ordered'));
  UPDATE PRIORITY_3 pr JOIN REORDER_LEVEL rl ON rl.id = pr.reorder_level_id
    JOIN PURCHASE_ORDER_ITEMS poi ON poi.raw_material_id = rl.raw_material_id AND poi.purchase_order_id = p_po_id
  SET pr.priority_status = 'Open'
  WHERE pr.priority_status = 'Ordered' AND NOT EXISTS (
    SELECT 1 FROM PURCHASE_ORDER_ITEMS x JOIN PURCHASE_ORDER po ON po.id = x.purchase_order_id
    WHERE x.raw_material_id = rl.raw_material_id AND po.id <> p_po_id AND po.purchase_order_status IN ('Pending','Ordered'));
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_delivery_status` (IN `p_delivery_id` INT UNSIGNED, IN `p_status` VARCHAR(20), IN `p_staff_id` INT UNSIGNED)   BEGIN
  DECLARE v_order INT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  SELECT order_id INTO v_order FROM DELIVERY WHERE id = p_delivery_id FOR UPDATE;
  IF v_order IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Delivery not found'; END IF;
  INSERT INTO DELIVERY_STATUS (delivery_id, delivery_status, updated_by_staff_id) VALUES (p_delivery_id, p_status, p_staff_id);
  IF p_status = 'Delivered' THEN UPDATE ORDERS SET order_status = 'Completed' WHERE id = v_order; END IF;
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_pickup_status` (IN `p_order_id` INT UNSIGNED, IN `p_status` VARCHAR(10), IN `p_staff_id` INT UNSIGNED)   BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  UPDATE PICKUP SET pickup_status = p_status WHERE order_id = p_order_id;
  IF p_status = 'Picked Up' THEN UPDATE ORDERS SET order_status = 'Completed' WHERE id = p_order_id; END IF;
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_use_raw_material` (IN `p_raw_material_id` INT UNSIGNED, IN `p_qty` DECIMAL(10,3), IN `p_staff_id` INT UNSIGNED)   BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SET @current_user_id = p_staff_id;
  INSERT INTO STOCK_OUT (raw_material_id, quantity_out, stock_out_reason, stock_out_date, recorded_by_staff_id)
  VALUES (p_raw_material_id, p_qty, 'Used', CURDATE(), p_staff_id);
  COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_write_audit` (IN `p_user_id` INT UNSIGNED, IN `p_table` VARCHAR(64), IN `p_record` INT UNSIGNED, IN `p_action` VARCHAR(10))   BEGIN
  IF p_user_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Set @current_user_id before changing data (audit requirement)';
  END IF;
  INSERT INTO AUDIT_LOGS (user_id, action_type, affected_table, record_id)
  VALUES (p_user_id, p_action, p_table, p_record);
END$$

DELIMITER ;

