--
-- Table structure for table `admin`
--

CREATE TABLE `admin` (
  `user_id` int(10) UNSIGNED NOT NULL,
  `authorization_level` tinyint(3) UNSIGNED NOT NULL DEFAULT 3
) ;

--
-- Dumping data for table `admin`
--

INSERT INTO `admin` (`user_id`, `authorization_level`) VALUES
(1, 3);

--
-- Triggers `admin`
--
DELIMITER $$
CREATE TRIGGER `trg_admin_bi` BEFORE INSERT ON `admin` FOR EACH ROW BEGIN
  IF (SELECT user_type FROM USER WHERE id = NEW.user_id) <> 'admin' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USER.user_type must be admin for this role table'; END IF;
END
$$
DELIMITER ;

