--
-- Triggers `customer`
--
DELIMITER $$
CREATE TRIGGER `trg_customer_bi` BEFORE INSERT ON `customer` FOR EACH ROW BEGIN
  IF (SELECT user_type FROM USER WHERE id = NEW.user_id) <> 'customer' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USER.user_type must be customer for this role table'; END IF;
END
$$
DELIMITER ;

