  `preferred_frosting` varchar(50) DEFAULT NULL,
  `reference_photo_path` varchar(255) DEFAULT NULL,
  `design_notes` text DEFAULT NULL,
  `quoted_price` decimal(8,2) DEFAULT NULL,
