--
-- Triggers `custom_orders`
--
DELIMITER $$
CREATE TRIGGER `trg_custom_orders_ai` AFTER INSERT ON `custom_orders` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'CUSTOM_ORDERS', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_custom_orders_au` AFTER UPDATE ON `custom_orders` FOR EACH ROW BEGIN
  IF NEW.quote_status = 'Rejected' AND OLD.quote_status <> 'Rejected' THEN CALL sp_write_audit(@current_user_id, 'CUSTOM_ORDERS', NEW.id, 'ARCHIVE');
  ELSEIF NOT (NEW.quote_status <=> OLD.quote_status AND NEW.quoted_price <=> OLD.quoted_price AND NEW.order_id <=> OLD.order_id AND NEW.reviewed_by_staff_id <=> OLD.reviewed_by_staff_id AND NEW.preferred_date <=> OLD.preferred_date) THEN CALL sp_write_audit(@current_user_id, 'CUSTOM_ORDERS', NEW.id, 'UPDATE');
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_custom_orders_bd` BEFORE DELETE ON `custom_orders` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;

