--
-- Triggers `delivery`
--
DELIMITER $$
CREATE TRIGGER `trg_delivery_ai` AFTER INSERT ON `delivery` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'DELIVERY', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_delivery_au` AFTER UPDATE ON `delivery` FOR EACH ROW BEGIN
  IF NOT (NEW.address_id <=> OLD.address_id AND NEW.recipient_first_name <=> OLD.recipient_first_name AND NEW.recipient_last_name <=> OLD.recipient_last_name) THEN CALL sp_write_audit(@current_user_id, 'DELIVERY', NEW.id, 'UPDATE'); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_delivery_bd` BEFORE DELETE ON `delivery` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_delivery_bi` BEFORE INSERT ON `delivery` FOR EACH ROW BEGIN
  DECLARE v_oc, v_ac INT UNSIGNED;
  SELECT customer_id INTO v_oc FROM ORDERS WHERE id = NEW.order_id;
  SELECT customer_id INTO v_ac FROM ADDRESSES WHERE id = NEW.address_id;
  IF v_oc <> v_ac THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The delivery address does not belong to the customer of this order'; END IF;
  IF EXISTS (SELECT 1 FROM PICKUP WHERE order_id = NEW.order_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This order is already set for pick-up'; END IF;
END
$$
DELIMITER ;

