--
-- Triggers `discarded_items`
--
DELIMITER $$
CREATE TRIGGER `trg_discarded_items_ai` AFTER INSERT ON `discarded_items` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'DISCARDED_ITEMS', NEW.id, 'CREATE');
  UPDATE INVENTORY_BATCHES SET stock_remaining = stock_remaining - NEW.quantity_discarded WHERE id = NEW.batch_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_discarded_items_au` AFTER UPDATE ON `discarded_items` FOR EACH ROW BEGIN
  IF NOT (NEW.quantity_discarded <=> OLD.quantity_discarded AND NEW.discard_reason <=> OLD.discard_reason AND NEW.discard_date <=> OLD.discard_date) THEN CALL sp_write_audit(@current_user_id, 'DISCARDED_ITEMS', NEW.id, 'UPDATE'); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_discarded_items_bd` BEFORE DELETE ON `discarded_items` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_discarded_items_bi` BEFORE INSERT ON `discarded_items` FOR EACH ROW BEGIN
  DECLARE v_rem SMALLINT UNSIGNED;
  SELECT stock_remaining INTO v_rem FROM INVENTORY_BATCHES WHERE id = NEW.batch_id;
  IF NEW.quantity_discarded > v_rem THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot discard more than the batch stock remaining'; END IF;
END
$$
DELIMITER ;

