--
-- Triggers `inventory_batches`
--
DELIMITER $$
CREATE TRIGGER `trg_inventory_batches_ai` AFTER INSERT ON `inventory_batches` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'INVENTORY_BATCHES', NEW.id, 'CREATE');
  CALL sp_sync_product_stock(NEW.product_id);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_inventory_batches_au` AFTER UPDATE ON `inventory_batches` FOR EACH ROW BEGIN
  IF NOT (NEW.quantity_added <=> OLD.quantity_added AND NEW.baked_date <=> OLD.baked_date) THEN CALL sp_write_audit(@current_user_id, 'INVENTORY_BATCHES', NEW.id, 'UPDATE'); END IF;
  CALL sp_sync_product_stock(NEW.product_id);
  IF OLD.product_id <> NEW.product_id THEN CALL sp_sync_product_stock(OLD.product_id); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_inventory_batches_bd` BEFORE DELETE ON `inventory_batches` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;

