--
-- Triggers `orders`
--
DELIMITER $$
CREATE TRIGGER `trg_orders_ai` AFTER INSERT ON `orders` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'ORDERS', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_orders_au` AFTER UPDATE ON `orders` FOR EACH ROW BEGIN
  IF NEW.order_status = 'Cancelled' AND OLD.order_status <> 'Cancelled' THEN CALL sp_write_audit(@current_user_id, 'ORDERS', NEW.id, 'ARCHIVE');
  ELSEIF NOT (NEW.order_status <=> OLD.order_status AND NEW.payment_method_id <=> OLD.payment_method_id AND NEW.preferred_date <=> OLD.preferred_date AND NEW.gcash_ref_number <=> OLD.gcash_ref_number) THEN CALL sp_write_audit(@current_user_id, 'ORDERS', NEW.id, 'UPDATE');
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_orders_bd` BEFORE DELETE ON `orders` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_orders_bu` BEFORE UPDATE ON `orders` FOR EACH ROW BEGIN
  IF OLD.order_status IN ('Completed','Cancelled') AND NEW.order_status <> OLD.order_status THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A Completed or Cancelled order cannot change status'; END IF;
END
$$
DELIMITER ;

