--
-- Triggers `purchase_order`
--
DELIMITER $$
CREATE TRIGGER `trg_purchase_order_ai` AFTER INSERT ON `purchase_order` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'PURCHASE_ORDER', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_purchase_order_au` AFTER UPDATE ON `purchase_order` FOR EACH ROW BEGIN
  IF NEW.purchase_order_status = 'Cancelled' AND OLD.purchase_order_status <> 'Cancelled' THEN CALL sp_write_audit(@current_user_id, 'PURCHASE_ORDER', NEW.id, 'ARCHIVE');
  ELSEIF NOT (NEW.purchase_order_status <=> OLD.purchase_order_status AND NEW.expected_date <=> OLD.expected_date AND NEW.supplier_name <=> OLD.supplier_name) THEN CALL sp_write_audit(@current_user_id, 'PURCHASE_ORDER', NEW.id, 'UPDATE');
  END IF;
  IF NEW.purchase_order_status IN ('Received','Cancelled') AND OLD.purchase_order_status NOT IN ('Received','Cancelled') THEN CALL sp_unmark_priority_ordered(NEW.id); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_purchase_order_bd` BEFORE DELETE ON `purchase_order` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;

