  IF (SELECT purchase_order_status FROM PURCHASE_ORDER WHERE id = NEW.purchase_order_id) IN ('Pending','Ordered') THEN CALL sp_mark_priority_ordered(NEW.raw_material_id); END IF;
END
$$
DELIMITER ;

