DELIMITER $$
CREATE TRIGGER `trg_raw_materials_ai` AFTER INSERT ON `raw_materials` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'RAW_MATERIALS', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_raw_materials_au` AFTER UPDATE ON `raw_materials` FOR EACH ROW BEGIN
  IF NEW.is_archived = 1 AND OLD.is_archived = 0 THEN CALL sp_write_audit(@current_user_id, 'RAW_MATERIALS', NEW.id, 'ARCHIVE');
  ELSEIF NOT (NEW.material_name <=> OLD.material_name AND NEW.unit_of_measure <=> OLD.unit_of_measure) THEN CALL sp_write_audit(@current_user_id, 'RAW_MATERIALS', NEW.id, 'UPDATE');
  END IF;
  IF NEW.is_archived <> OLD.is_archived THEN CALL sp_refresh_priority(NEW.id); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_raw_materials_bd` BEFORE DELETE ON `raw_materials` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;

