--
-- Triggers `sales`
--
DELIMITER $$
CREATE TRIGGER `trg_sales_ai` AFTER INSERT ON `sales` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'SALES', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_sales_au` AFTER UPDATE ON `sales` FOR EACH ROW BEGIN
  IF NOT (NEW.sale_date <=> OLD.sale_date) THEN CALL sp_write_audit(@current_user_id, 'SALES', NEW.id, 'UPDATE'); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_sales_bd` BEFORE DELETE ON `sales` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;

