--
-- Table structure for table `staff`
--

CREATE TABLE `staff` (
  `user_id` int(10) UNSIGNED NOT NULL,
  `authorization_level` tinyint(3) UNSIGNED NOT NULL DEFAULT 2,
  `job_title` varchar(50) DEFAULT NULL,
  `hired_date` date DEFAULT NULL
) ;

