--
-- Triggers `staff`
--
DELIMITER $$
CREATE TRIGGER `trg_staff_bi` BEFORE INSERT ON `staff` FOR EACH ROW BEGIN
  IF (SELECT user_type FROM USER WHERE id = NEW.user_id) <> 'staff' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'USER.user_type must be staff for this role table'; END IF;
END
$$
DELIMITER ;

