--
-- Triggers `stock_in`
--
DELIMITER $$
CREATE TRIGGER `trg_stock_in_ai` AFTER INSERT ON `stock_in` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'STOCK_IN', NEW.id, 'CREATE');
  UPDATE RAW_MATERIALS SET quantity_on_hand = quantity_on_hand + NEW.quantity_in WHERE id = NEW.raw_material_id;
  CALL sp_refresh_priority(NEW.raw_material_id);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_in_au` AFTER UPDATE ON `stock_in` FOR EACH ROW BEGIN
  IF NOT (NEW.unit_cost <=> OLD.unit_cost AND NEW.received_date <=> OLD.received_date AND NEW.purchase_order_id <=> OLD.purchase_order_id) THEN CALL sp_write_audit(@current_user_id, 'STOCK_IN', NEW.id, 'UPDATE'); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_in_bd` BEFORE DELETE ON `stock_in` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_in_bu` BEFORE UPDATE ON `stock_in` FOR EACH ROW BEGIN
  IF NEW.raw_material_id <> OLD.raw_material_id OR NEW.quantity_in <> OLD.quantity_in THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stock movements are a ledger: material and quantity cannot be edited'; END IF;
END
$$
DELIMITER ;

