--
-- Triggers `stock_out`
--
DELIMITER $$
CREATE TRIGGER `trg_stock_out_ai` AFTER INSERT ON `stock_out` FOR EACH ROW BEGIN
  CALL sp_write_audit(@current_user_id, 'STOCK_OUT', NEW.id, 'CREATE');
  UPDATE RAW_MATERIALS SET quantity_on_hand = quantity_on_hand - NEW.quantity_out WHERE id = NEW.raw_material_id;
  CALL sp_refresh_priority(NEW.raw_material_id);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_out_au` AFTER UPDATE ON `stock_out` FOR EACH ROW BEGIN
  IF NOT (NEW.stock_out_reason <=> OLD.stock_out_reason AND NEW.stock_out_date <=> OLD.stock_out_date AND NEW.discarded_item_id <=> OLD.discarded_item_id) THEN CALL sp_write_audit(@current_user_id, 'STOCK_OUT', NEW.id, 'UPDATE'); END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_out_bd` BEFORE DELETE ON `stock_out` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_out_bi` BEFORE INSERT ON `stock_out` FOR EACH ROW BEGIN
  DECLARE v_on DECIMAL(10,3);
  SELECT quantity_on_hand INTO v_on FROM RAW_MATERIALS WHERE id = NEW.raw_material_id;
  IF NEW.quantity_out > v_on THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not enough raw material in stock'; END IF;
  IF NEW.discarded_item_id IS NOT NULL AND NEW.stock_out_reason NOT IN ('Discarded','Expired') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A stock-out linked to a discarded item must have reason Discarded or Expired'; END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_stock_out_bu` BEFORE UPDATE ON `stock_out` FOR EACH ROW BEGIN
  IF NEW.raw_material_id <> OLD.raw_material_id OR NEW.quantity_out <> OLD.quantity_out THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stock movements are a ledger: material and quantity cannot be edited'; END IF;
  IF NEW.discarded_item_id IS NOT NULL AND NEW.stock_out_reason NOT IN ('Discarded','Expired') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A stock-out linked to a discarded item must have reason Discarded or Expired'; END IF;
END
$$
DELIMITER ;

