--
-- Triggers `user`
--
DELIMITER $$
CREATE TRIGGER `trg_user_ai` AFTER INSERT ON `user` FOR EACH ROW BEGIN
  CALL sp_write_audit(COALESCE(@current_user_id, NEW.id), 'USER', NEW.id, 'CREATE');
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_user_au` AFTER UPDATE ON `user` FOR EACH ROW BEGIN
  IF NEW.status = 'Archived' AND OLD.status <> 'Archived' THEN CALL sp_write_audit(COALESCE(@current_user_id, NEW.id), 'USER', NEW.id, 'ARCHIVE');
  ELSEIF NOT (NEW.username <=> OLD.username AND NEW.first_name <=> OLD.first_name AND NEW.last_name <=> OLD.last_name AND NEW.password_hash <=> OLD.password_hash AND NEW.phone_number <=> OLD.phone_number AND NEW.status <=> OLD.status) THEN CALL sp_write_audit(COALESCE(@current_user_id, NEW.id), 'USER', NEW.id, 'UPDATE');
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_user_bd` BEFORE DELETE ON `user` FOR EACH ROW BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Records are archived, never deleted (CRUA policy)';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_user_bu` BEFORE UPDATE ON `user` FOR EACH ROW BEGIN
  IF NEW.user_type <> OLD.user_type THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'user_type cannot be changed'; END IF;
END
$$
DELIMITER ;

