--
-- Structure for view `v_audit_trail`
--
DROP TABLE IF EXISTS `v_audit_trail`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_audit_trail`  AS SELECT `a`.`id` AS `audit_id`, `a`.`performed_at` AS `performed_at`, concat(`u`.`first_name`,' ',`u`.`last_name`) AS `performed_by`, `u`.`user_type` AS `role`, `a`.`action_type` AS `action_type`, `a`.`affected_table` AS `affected_table`, `a`.`record_id` AS `record_id` FROM (`audit_logs` `a` join `user` `u` on(`u`.`id` = `a`.`user_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_batch_expiry`
--
DROP TABLE IF EXISTS `v_batch_expiry`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_batch_expiry`  AS SELECT `b`.`id` AS `batch_id`, `p`.`product_name` AS `product_name`, `b`.`baked_date` AS `baked_date`, `b`.`quantity_added` AS `quantity_added`, `b`.`stock_remaining` AS `stock_remaining`, `b`.`baked_date`+ interval `p`.`shelf_life_days` day AS `expiry_date`, to_days(`b`.`baked_date` + interval `p`.`shelf_life_days` day) - to_days(curdate()) AS `days_left`, CASE WHEN `b`.`stock_remaining` = 0 THEN 'Sold out / discarded' WHEN `b`.`baked_date` + interval `p`.`shelf_life_days` day < curdate() THEN 'Expired' WHEN to_days(`b`.`baked_date` + interval `p`.`shelf_life_days` day) - to_days(curdate()) <= 2 THEN 'Expiring soon' ELSE 'Fresh' END AS `freshness` FROM (`inventory_batches` `b` join `products` `p` on(`p`.`id` = `b`.`product_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_current_delivery_status`
--
DROP TABLE IF EXISTS `v_current_delivery_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_current_delivery_status`  AS SELECT `x`.`delivery_id` AS `delivery_id`, `x`.`delivery_status` AS `delivery_status`, `x`.`updated_at` AS `updated_at` FROM (select `ds`.`delivery_id` AS `delivery_id`,`ds`.`delivery_status` AS `delivery_status`,`ds`.`updated_at` AS `updated_at`,row_number() over ( partition by `ds`.`delivery_id` order by `ds`.`updated_at` desc,`ds`.`id` desc) AS `rn` from `delivery_status` `ds`) AS `x` WHERE `x`.`rn` = 1 ;

-- --------------------------------------------------------

--
-- Structure for view `v_custom_order_queue`
--
DROP TABLE IF EXISTS `v_custom_order_queue`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_custom_order_queue`  AS SELECT `co`.`id` AS `custom_order_id`, concat(`u`.`first_name`,' ',`u`.`last_name`) AS `customer_name`, `co`.`cake_flavor` AS `cake_flavor`, `co`.`cake_size` AS `cake_size`, `co`.`cake_theme` AS `cake_theme`, `co`.`preferred_date` AS `preferred_date`, `co`.`quote_status` AS `quote_status`, `co`.`quoted_price` AS `quoted_price` FROM (`custom_orders` `co` join `user` `u` on(`u`.`id` = `co`.`customer_id`)) WHERE `co`.`quote_status` in ('Pending','Quoted') ;

-- --------------------------------------------------------

--
-- Structure for view `v_daily_sales`
--
DROP TABLE IF EXISTS `v_daily_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_daily_sales`  AS SELECT `s`.`sale_date` AS `sale_date`, count(0) AS `orders_sold`, sum(`o`.`total_amount`) AS `total_sales` FROM (`sales` `s` join `orders` `o` on(`o`.`id` = `s`.`order_id`)) GROUP BY `s`.`sale_date` ;

-- --------------------------------------------------------

--
-- Structure for view `v_low_stock_materials`
--
DROP TABLE IF EXISTS `v_low_stock_materials`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_low_stock_materials`  AS SELECT `rm`.`id` AS `raw_material_id`, `rm`.`material_name` AS `material_name`, `rm`.`unit_of_measure` AS `unit_of_measure`, `rm`.`quantity_on_hand` AS `quantity_on_hand`, `rl`.`priority1_qty` AS `priority1_qty`, `rl`.`priority2_qty` AS `priority2_qty`, `rl`.`priority3_qty` AS `priority3_qty`, CASE WHEN `rm`.`quantity_on_hand` <= `rl`.`priority1_qty` THEN 1 WHEN `rm`.`quantity_on_hand` <= `rl`.`priority2_qty` THEN 2 WHEN `rm`.`quantity_on_hand` <= `rl`.`priority3_qty` THEN 3 END AS `priority_level` FROM (`raw_materials` `rm` join `reorder_level` `rl` on(`rl`.`raw_material_id` = `rm`.`id`)) WHERE `rm`.`is_archived` = 0 AND `rm`.`quantity_on_hand` <= `rl`.`priority3_qty` ;

-- --------------------------------------------------------

--
-- Structure for view `v_order_summary`
--
DROP TABLE IF EXISTS `v_order_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_order_summary`  AS SELECT `o`.`id` AS `order_id`, `o`.`order_date` AS `order_date`, concat(`u`.`first_name`,' ',`u`.`last_name`) AS `customer_name`, `pm`.`method_name` AS `payment_method`, `o`.`order_status` AS `order_status`, `o`.`total_amount` AS `total_amount`, `o`.`preferred_date` AS `preferred_date`, CASE WHEN `d`.`id` is not null THEN 'Delivery' WHEN `pu`.`id` is not null THEN 'Pick-up' ELSE 'Not set' END AS `fulfillment_type`, coalesce(`cds`.`delivery_status`,`pu`.`pickup_status`,case when `d`.`id` is not null then 'No update yet' end) AS `fulfillment_status`, CASE WHEN `co`.`id` is null THEN 'Regular' ELSE 'Custom' END AS `order_kind` FROM ((((((`orders` `o` join `user` `u` on(`u`.`id` = `o`.`customer_id`)) join `payment_method` `pm` on(`pm`.`id` = `o`.`payment_method_id`)) left join `delivery` `d` on(`d`.`order_id` = `o`.`id`)) left join `v_current_delivery_status` `cds` on(`cds`.`delivery_id` = `d`.`id`)) left join `pickup` `pu` on(`pu`.`order_id` = `o`.`id`)) left join `custom_orders` `co` on(`co`.`order_id` = `o`.`id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_pending_purchase_orders`
--
DROP TABLE IF EXISTS `v_pending_purchase_orders`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_pending_purchase_orders`  AS SELECT `po`.`id` AS `purchase_order_id`, `po`.`supplier_name` AS `supplier_name`, `ty`.`type_name` AS `type_name`, `po`.`order_date` AS `order_date`, `po`.`expected_date` AS `expected_date`, `po`.`purchase_order_status` AS `purchase_order_status`, count(`poi`.`id`) AS `item_count`, round(sum(`poi`.`quantity_ordered` * `poi`.`unit_cost`),2) AS `estimated_cost` FROM ((`purchase_order` `po` join `type` `ty` on(`ty`.`id` = `po`.`type_id`)) left join `purchase_order_items` `poi` on(`poi`.`purchase_order_id` = `po`.`id`)) WHERE `po`.`purchase_order_status` in ('Pending','Ordered') GROUP BY `po`.`id`, `po`.`supplier_name`, `ty`.`type_name`, `po`.`order_date`, `po`.`expected_date`, `po`.`purchase_order_status` ;

-- --------------------------------------------------------

--
-- Structure for view `v_priority_containers`
--
DROP TABLE IF EXISTS `v_priority_containers`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_priority_containers`  AS SELECT 1 AS `priority_level`, `rm`.`material_name` AS `material_name`, `rm`.`quantity_on_hand` AS `quantity_on_hand`, `pr`.`priority_status` AS `priority_status`, `pr`.`flagged_at` AS `flagged_at` FROM ((`priority_1` `pr` join `reorder_level` `rl` on(`rl`.`id` = `pr`.`reorder_level_id`)) join `raw_materials` `rm` on(`rm`.`id` = `rl`.`raw_material_id`))union all select 2 AS `2`,`rm`.`material_name` AS `material_name`,`rm`.`quantity_on_hand` AS `quantity_on_hand`,`pr`.`priority_status` AS `priority_status`,`pr`.`flagged_at` AS `flagged_at` from ((`priority_2` `pr` join `reorder_level` `rl` on(`rl`.`id` = `pr`.`reorder_level_id`)) join `raw_materials` `rm` on(`rm`.`id` = `rl`.`raw_material_id`)) union all select 3 AS `3`,`rm`.`material_name` AS `material_name`,`rm`.`quantity_on_hand` AS `quantity_on_hand`,`pr`.`priority_status` AS `priority_status`,`pr`.`flagged_at` AS `flagged_at` from ((`priority_3` `pr` join `reorder_level` `rl` on(`rl`.`id` = `pr`.`reorder_level_id`)) join `raw_materials` `rm` on(`rm`.`id` = `rl`.`raw_material_id`))  ;

-- --------------------------------------------------------

--
-- Structure for view `v_product_catalog`
--
DROP TABLE IF EXISTS `v_product_catalog`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_product_catalog`  AS SELECT `p`.`id` AS `product_id`, `p`.`product_name` AS `product_name`, `ty`.`type_name` AS `type_name`, `p`.`product_price` AS `product_price`, `p`.`total_stock` AS `total_stock`, `p`.`baked_date` AS `baked_date`, `p`.`baked_date`+ interval `p`.`shelf_life_days` day AS `best_before_date`, CASE WHEN `p`.`total_stock` = 0 THEN 'Out of stock' ELSE 'Available' END AS `availability` FROM (`products` `p` join `type` `ty` on(`ty`.`id` = `p`.`type_id`)) WHERE `p`.`is_archived` = 0 ;

-- --------------------------------------------------------

--
-- Structure for view `v_stock_movements`
--
DROP TABLE IF EXISTS `v_stock_movements`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_stock_movements`  AS SELECT `si`.`received_date` AS `movement_date`, 'IN' AS `direction`, `rm`.`material_name` AS `material_name`, `si`.`quantity_in` AS `quantity`, `rm`.`unit_of_measure` AS `unit_of_measure`, 'Received' AS `reason`, concat(`u`.`first_name`,' ',`u`.`last_name`) AS `recorded_by` FROM ((`stock_in` `si` join `raw_materials` `rm` on(`rm`.`id` = `si`.`raw_material_id`)) join `user` `u` on(`u`.`id` = `si`.`received_by_staff_id`))union all select `so`.`stock_out_date` AS `stock_out_date`,'OUT' AS `OUT`,`rm`.`material_name` AS `material_name`,`so`.`quantity_out` AS `quantity_out`,`rm`.`unit_of_measure` AS `unit_of_measure`,`so`.`stock_out_reason` AS `stock_out_reason`,concat(`u`.`first_name`,' ',`u`.`last_name`) AS `CONCAT(u.first_name, ' ', u.last_name)` from ((`stock_out` `so` join `raw_materials` `rm` on(`rm`.`id` = `so`.`raw_material_id`)) join `user` `u` on(`u`.`id` = `so`.`recorded_by_staff_id`))  ;

